import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:flutter_test/flutter_test.dart';import 'package:hustle_mobile/main.dart';import 'package:hustle_mobile/features/analysis/domain/analysis.dart';import 'package:hustle_mobile/features/analysis/presentation/analysis_controller.dart';
class FakeController extends AnalysisController{FakeController(this.value);final AsyncValue<Analysis?> value;@override Future<Analysis?> build()async{state=value;return value.valueOrNull;}@override Future<void> analyze(String s,String i)async{}}
Analysis sample()=>Analysis(sourceService:'x',sourceEventId:'1',symbol:'BTCUSDT',exchange:'BINANCE',timeframe:'1h',action:SignalAction.hold,confidence:.4,price:10,signalTime:DateTime(2026),reasons:const ['Nötr'],indicators:Indicators.fromJson({}));
void main(){testWidgets('ana ekran temel kontrolleri gösterir',(tester)async{await tester.pumpWidget(const ProviderScope(child:MaterialApp(home:HomeScreen())));await tester.pump();expect(find.text('Analiz et'),findsOneWidget);expect(find.byKey(const Key('symbolField')),findsOneWidget);});testWidgets('yükleniyor durumunu gösterir',(tester)async{await tester.pumpWidget(ProviderScope(overrides:[analysisProvider.overrideWith(()=>FakeController(const AsyncLoading()))],child:const MaterialApp(home:HomeScreen())));await tester.pump();expect(find.byType(CircularProgressIndicator),findsOneWidget);});testWidgets('başarı ve hata durumları',(tester)async{await tester.pumpWidget(ProviderScope(overrides:[analysisProvider.overrideWith(()=>FakeController(AsyncData(sample())))],child:const MaterialApp(home:HomeScreen())));await tester.pump();expect(find.byKey(const Key('signalCard')),findsOneWidget);await tester.pumpWidget(ProviderScope(overrides:[analysisProvider.overrideWith(()=>FakeController(AsyncError(Exception('hata'),StackTrace.empty)))],child:const MaterialApp(home:HomeScreen())));await tester.pump();expect(find.text('Yeniden dene'),findsOneWidget);});}
